import 'package:exam_grading/config/api_config.dart'; import 'package:exam_grading/config/firebase_options.dart'; import 'package:exam_grading/presentation/screens/login_screen.dart'; import 'package:exam_grading/presentation/screens/dashboard_screen.dart'; import 'package:exam_grading/presentation/theme/app_colors.dart'; import 'package:firebase_auth/firebase_auth.dart'; import 'package:firebase_core/firebase_core.dart'; import 'package:flutter/material.dart'; import 'package:flutter_dotenv/flutter_dotenv.dart'; import 'package:flutter_native_splash/flutter_native_splash.dart'; import 'package:google_fonts/google_fonts.dart'; import 'package:loading_animation_widget/loading_animation_widget.dart';  class ExamScannerApp extends StatelessWidget {   const ExamScannerApp({super.key});    @override   Widget build(BuildContext context) {     return MaterialApp(       title: 'Exam Scanner',       debugShowCheckedModeBanner: false,       theme: ThemeData(         useMaterial3: true,         colorScheme: ColorScheme.fromSeed(           seedColor: AppColors.primary,           primary: AppColors.primary,           surface: AppColors.background,         ),         textTheme: GoogleFonts.kanitTextTheme(Theme.of(context).textTheme),         appBarTheme: AppBarTheme(           backgroundColor: AppColors.primary,           foregroundColor: Colors.white,           elevation: 0,           centerTitle: true,           titleTextStyle: GoogleFonts.kanit(             fontSize: 20,             fontWeight: FontWeight.w600,             color: Colors.white,           ),         ),         cardTheme: CardThemeData(           elevation: 2,           shape: RoundedRectangleBorder(             borderRadius: BorderRadius.circular(16),           ),           color: Colors.white,         ),         elevatedButtonTheme: ElevatedButtonThemeData(           style: ElevatedButton.styleFrom(             elevation: 0,             padding: const EdgeInsets.symmetric(vertical: 16, horizontal: 24),             shape: RoundedRectangleBorder(               borderRadius: BorderRadius.circular(12),             ),             backgroundColor: AppColors.primary,             foregroundColor: Colors.white,           ),         ),         inputDecorationTheme: InputDecorationTheme(           filled: true,           fillColor: Colors.white,           border: OutlineInputBorder(             borderRadius: BorderRadius.circular(12),             borderSide: const BorderSide(color: AppColors.border),           ),           enabledBorder: OutlineInputBorder(             borderRadius: BorderRadius.circular(12),             borderSide: const BorderSide(color: AppColors.border),           ),           focusedBorder: OutlineInputBorder(             borderRadius: BorderRadius.circular(12),             borderSide: const BorderSide(color: AppColors.primary, width: 2),           ),           contentPadding: const EdgeInsets.symmetric(             horizontal: 16,             vertical: 16,           ),         ),       ),       home: const SplashScreen(),     );   } }  class SplashScreen extends StatefulWidget {   const SplashScreen({super.key});    @override   State<SplashScreen> createState() => _SplashScreenState(); }  class _SplashScreenState extends State<SplashScreen> {   @override   void initState() {     super.initState();     WidgetsBinding.instance.addPostFrameCallback((_) => _initializeApp());   }    @override   void dispose() {     super.dispose();   }    Future<void> _initializeApp() async {     try {       FlutterNativeSplash.remove();       await _waitForSplashStep();       await dotenv.load(fileName: '.env');        await _waitForSplashStep();       await Firebase.initializeApp(options: firebaseOptions);       debugPrint('FastAPI URL: ${ApiConfig.baseUrl} (${ApiConfig.source})');        await _waitForSplashStep();       await Future.delayed(const Duration(milliseconds: 450));        if (!mounted) return;       Navigator.pushReplacement(context, _fadeRoute(const AuthWrapper()));     } catch (error) {       FlutterNativeSplash.remove();       if (!mounted) return;       debugPrint('Splash initialization failed: $error');     }   }    Future<void> _waitForSplashStep() async {     await Future.delayed(const Duration(milliseconds: 300));   }    @override   Widget build(BuildContext context) {     return Scaffold(       body: Container(         decoration: const BoxDecoration(           color: Color(0xFF2563EB),         ),         child: Center(           child: Column(             mainAxisAlignment: MainAxisAlignment.center,             children: [               const Spacer(flex: 3),               Container(                 width: 140,                 height: 140,                 decoration: BoxDecoration(                   borderRadius: BorderRadius.circular(24),                   boxShadow: [                     BoxShadow(                       color: Colors.black.withValues(alpha: 0.2),                       blurRadius: 20,                       offset: const Offset(0, 10),                     ),                   ],                 ),                 child: ClipRRect(                   borderRadius: BorderRadius.circular(24),                   child: Image.asset('images/icon.png'),                 ),               ),               const SizedBox(height: 24),               Text(                 'Exam Grading',                 style: GoogleFonts.kanit(                   color: Colors.white,                   fontSize: 32,                   fontWeight: FontWeight.bold,                   letterSpacing: 1.2,                 ),               ),               const SizedBox(height: 8),               Text(                 'ตรวจข้อสอบง่ายๆ แค่ปลายนิ้ว',                 style: GoogleFonts.kanit(                   color: Colors.white.withValues(alpha: 0.8),                   fontSize: 16,                   fontWeight: FontWeight.w500,                 ),               ),               const Spacer(flex: 2),               LoadingAnimationWidget.threeArchedCircle(                 color: Colors.white,                 size: 50,               ),               const SizedBox(height: 16),               Text(                 'กำลังเตรียมความพร้อม...',                 style: GoogleFonts.kanit(                   color: Colors.white.withValues(alpha: 0.9),                   fontSize: 14,                 ),               ),               const Spacer(flex: 1),             ],           ),         ),       ),     );   } }  class AuthWrapper extends StatefulWidget {   const AuthWrapper({super.key});    @override   State<AuthWrapper> createState() => _AuthWrapperState(); }  class _AuthWrapperState extends State<AuthWrapper> {   @override   void initState() {     super.initState();     WidgetsBinding.instance.addPostFrameCallback((_) {       _checkAuth();     });   }    void _checkAuth() {     final user = FirebaseAuth.instance.currentUser;     if (user != null) {       Navigator.pushReplacement(context, _fadeRoute(const DashboardScreen()));     } else {       Navigator.pushReplacement(context, _fadeRoute(const LoginScreen()));     }   }    @override   Widget build(BuildContext context) {     return Scaffold(       backgroundColor: const Color(0xFFF8FAFC),       body: Center(         child: LoadingAnimationWidget.discreteCircle(           color: const Color(0xFF2563EB),           secondRingColor: const Color(0xFF10B981),           thirdRingColor: const Color(0xFFF59E0B),           size: 58,         ),       ),     );   } }  PageRouteBuilder<void> _fadeRoute(Widget page) {   return PageRouteBuilder<void>(     transitionDuration: const Duration(milliseconds: 650),     reverseTransitionDuration: const Duration(milliseconds: 350),     pageBuilder: (context, animation, secondaryAnimation) => page,     transitionsBuilder: (context, animation, secondaryAnimation, child) {       final curvedAnimation = CurvedAnimation(         parent: animation,         curve: Curves.easeOutCubic,       );       return FadeTransition(opacity: curvedAnimation, child: child);     },   ); }